import {printFields,fillPrintFields,readPrintFields} from './print-settings.js?v=20261025-release1';
import {comicConfig,comicGuides} from './comic-format.js?v=20261025-release1';
export function setupNewCanvas(create,toast){
 const dialog=document.createElement('dialog');dialog.id='newWebtoon';
 dialog.innerHTML=`<form id="newWebtoonForm"><div class="modal-head"><h2>새 캔버스</h2><button type="button" id="cancelNew" aria-label="새 캔버스 닫기">✕</button></div>
 <div class="canvas-tracks" role="group" aria-label="원고 형식"><button type="button" data-format="webtoon" aria-pressed="true"><b>웹툰</b><small>긴 세로 스크롤 · px</small></button><button type="button" data-format="comic" aria-pressed="false"><b>출판만화</b><small>일본 만화 · 동인지 · mm</small></button></div>
 <label>작품명<input id="newTitle" value="이름 없는 이야기" maxlength="80" required></label>
 <div class="canvas-setup"><div class="canvas-presets" aria-label="캔버스 프리셋"><section data-track="webtoon"><button type="button" data-size="1600,10000,300,3" class="active">세로 스크롤<small>1600 × 10000 px · 3페이지</small></button><button type="button" data-size="800,12000,300,1">모바일 원고<small>800 × 12000 px</small></button><button type="button" data-size="2000,20000,300,3">넓은 원고<small>2000 × 20000 px</small></button><button type="button" data-size="3000,3000,300,1">정사각형<small>3000 × 3000 px</small></button></section><section data-track="comic" hidden><button type="button" data-print="210,297,182,257,3,12">B5 만화 · A4 용지<small>재단 182 × 257 mm</small></button><button type="button" data-print="216,303,210,297,3,15">A4 만화<small>재단 210 × 297 mm</small></button><button type="button" data-print="154,216,148,210,3,10">A5 만화<small>재단 148 × 210 mm</small></button><p>파랑: 재단선<br>보라: 안쪽 여백<br>회색: 도련 바깥선</p></section></div>
 <div><div class="canvas-dimensions"><label>해상도 · dpi<select id="newDpi"><option>72</option><option>150</option><option selected>300</option><option>600</option></select></label><label><span id="newCountLabel">페이지 수</span><input id="newPageCount" type="number" min="1" max="200" value="3" required></label></div>
 <section data-track="webtoon"><div class="canvas-dimensions"><label>가로 · px<input id="newWidth" type="number" min="320" max="8192" value="1600" required></label><label>세로 · px<input id="newHeight" type="number" min="320" max="20000" value="10000" required></label></div></section>
 <section data-track="comic" hidden><div class="canvas-dimensions"><label>용지 가로 · mm<input id="paperWidthMm" type="number" min="20" max="690" step="0.1" value="210" required></label><label>용지 세로 · mm<input id="paperHeightMm" type="number" min="20" max="1500" step="0.1" value="297" required></label><label>재단 가로 · mm<input id="trimWidthMm" type="number" min="20" step="0.1" value="182" required></label><label>재단 세로 · mm<input id="trimHeightMm" type="number" min="20" step="0.1" value="257" required></label><label>도련 · mm<input id="bleedMm" type="number" min="0" max="20" step="0.5" value="3" required></label><label>기본 여백 · mm<input id="innerMarginMm" type="number" min="0" max="50" step="0.5" value="12" required></label></div><details id="newPrintAdvanced"><summary>제본 방향 · 쪽 번호 · 표지 · 여백</summary>${printFields('new')}<label class="check"><input id="newCovers" type="checkbox" checked>표지·뒤표지와 안쪽 4면 포함 (본문 수와 별도)</label></details><small>도련은 재단선 바깥, 안쪽 여백은 재단선 안쪽입니다. 안내선은 이미지로 출력되지 않습니다.</small></section>
 <button type="button" id="swapCanvas">↔ 가로·세로 바꾸기</button><figure id="canvasSizePreview"><div class="canvas-preview-stage"><span id="canvasPreviewPaper"></span></div><figcaption id="canvasPreviewLabel"></figcaption></figure><div id="newSummary" aria-live="polite"></div><button class="primary full" type="submit">캔버스 만들기</button></div></div></form>`;
 document.body.append(dialog);const $=id=>dialog.querySelector('#'+id),ids=['paperWidthMm','paperHeightMm','trimWidthMm','trimHeightMm','bleedMm','innerMarginMm'];let format='webtoon';
 function config(){const c={title:$('newTitle').value.trim()||'이름 없는 이야기',dpi:+$('newDpi').value,count:+$('newPageCount').value,format};if(c.count+(format==='comic'&&$('newCovers').checked?4:0)>200)throw Error('표지를 포함해 200페이지까지 지원합니다.');return format==='comic'?comicConfig({...c,comic:{...Object.fromEntries(ids.map(id=>[id,+$(id).value])),...readPrintFields(dialog)},covers:$('newCovers').checked}):{...c,width:+$('newWidth').value,pageHeight:+$('newHeight').value};}
 function summary(){try{const p=config();if(p.count+(p.covers?4:0)>200)throw Error('표지를 포함해 200페이지까지 지원합니다.');const w=p.width,h=p.pageHeight,k=Math.min(94/w,100/h),paper=$('canvasPreviewPaper');Object.assign(paper.style,{width:w*k+'px',height:h*k+'px'});paper.replaceChildren();for(const g of comicGuides(p)){const rect=document.createElement('i');rect.dataset.guide=g.kind;Object.assign(rect.style,{left:g.x*k+'px',top:g.y*k+'px',width:g.w*k+'px',height:g.h*k+'px'});paper.append(rect);}$('canvasPreviewLabel').textContent=format==='comic'?'용지 · 재단선 · 안쪽 여백':w>h?'가로형':'세로형';$('newSummary').textContent=`${w} × ${h} px · ${p.dpi} dpi · 총 ${p.count+(p.covers?4:0)}페이지${p.covers?' (본문 '+p.count+' + 표지 4면)':''}${format==='comic'?' · '+(p.comic.binding==='right'?'우철 · 오른쪽 → 왼쪽':'좌철 · 왼쪽 → 오른쪽')+' · 첫 본문 '+(p.comic.firstSide==='left'?'왼쪽':'오른쪽'):''}`;}catch(e){$('newSummary').textContent=e.message;}}
 function track(next){format=next;dialog.querySelectorAll('[data-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.format===format)));dialog.querySelectorAll('[data-track]').forEach(s=>{s.hidden=s.dataset.track!==format;s.querySelectorAll('input,select').forEach(i=>i.disabled=s.hidden);});$('newPageCount').value=format==='comic'?4:3;$('newCountLabel').textContent=format==='comic'?'본문 페이지 수':'페이지 수';summary();}
 dialog.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>track(b.dataset.format));
 dialog.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{b.dataset.size.split(',').forEach((v,i)=>$( ['newWidth','newHeight','newDpi','newPageCount'][i]).value=v);summary();});
 dialog.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>{b.dataset.print.split(',').forEach((v,i)=>$(ids[i]).value=v);fillPrintFields(dialog,{innerMarginMm:+$('innerMarginMm').value,folioStart:$('newCovers').checked?3:1});summary();});
 fillPrintFields(dialog,{folioStart:3});$('innerMarginMm').addEventListener('input',()=>{for(const key of ['gutterMm','outerMm','topMm','bottomMm'])dialog.querySelector('[data-print-setting='+key+']').value=$('innerMarginMm').value;});dialog.querySelector('[data-print-setting=binding]').addEventListener('change',e=>{dialog.querySelector('[data-print-setting=firstSide]').value=e.target.value==='left'?'right':'left';summary();});dialog.addEventListener('input',summary);$('swapCanvas').onclick=()=>{for(const [a,b]of format==='comic'?[['paperWidthMm','paperHeightMm'],['trimWidthMm','trimHeightMm']]:[['newWidth','newHeight']]){const v=$(a).value;$(a).value=$(b).value;$(b).value=v;}summary();};
 $('cancelNew').onclick=()=>dialog.close();$('newWebtoonForm').onsubmit=e=>{e.preventDefault();if(!$('newWebtoonForm').reportValidity())return;try{const p=config();create(p);dialog.close();}catch(e){toast(e.message);summary();}};track(format);
 return {open:()=>{summary();dialog.showModal();}};
}
